namespace App\Jobs;

use App\Models\Organization;
use App\Services\TaxFormService;
use Illuminate\Bus\Queueable;
use Illuminate\Contracts\Queue\ShouldQueue;
use Illuminate\Foundation\Bus\Dispatchable;
use Illuminate\Support\Facades\Storage;

class BatchGenerateTaxFormsJob implements ShouldQueue
{
    use Dispatchable, Queueable;

    public function __construct(public int $organizationId, public array $employeeIds, public string $filename)
    {
    }

    public function handle(TaxFormService $taxService): void
    {
        $org = Organization::findOrFail($this->organizationId);
        $employees = $org->employees()->whereIn('id', $this->employeeIds)->get();
        $zipArchive = $taxService->generateBulkP60Forms($employees);
        Storage::disk('secure_vault')->put("orgs/{$this->organizationId}/tax/{$this->filename}", $zipArchive);
    }
}
